def alien_order(words):
    adj = {c: set() for w in words for c in w}
    indeg = {c: 0 for c in adj}
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]                        # only ADJACENT pairs
        min_len = min(len(w1), len(w2))
        found = False
        for j in range(min_len):
            if w1[j] != w2[j]:
                if w2[j] not in adj[w1[j]]:
                    adj[w1[j]].add(w2[j])
                    indeg[w2[j]] += 1
                found = True
                break
        if not found and len(w1) > len(w2):
            return ''                                              # invalid: longer word sorts before its prefix
    queue = [c for c in indeg if indeg[c] == 0]
    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return ''.join(result) if len(result) == len(indeg) else ''

